	  if (p[i].size() != 4){
		return false;
	  }
	  if (p[i][1] - p[i][0] == p[i][2] - p[i][1] || 
		  p[i][3] - p[i][2] == p[i][2] - p[i][1] || 
		  p[i][3] - p[i][2] == p[i][1] - p[i][0]){
		return false;
	  }
	}
