const int INF = 1000000007;

void solve(){
	int n, k;
	cin >> n >> k;
	string s;
	cin >> s;

	int val_ans = INF;
	string ans(n, '0');

	for (int i = 0; i <= n; i++){
		string t = s;
		string cur_ans(n, '0');
		int cur_k = k;

		for (int j = 0; j < i; j++){
			if (t[j] == '(' && cur_k > 0){
				cur_ans[j] = '1';
				t[j] = ')';
				cur_k--;
			}
		}
		for (int j = n - 1; j > i; j--){
			if (t[j] == ')' && cur_k > 0){
				cur_ans[j] = '1';
				t[j] = '(';
				cur_k--;
			}
		}
		int val_cur = 0;
		int bal = 0;
		for (int j = 0; j < n; j++){
			if (bal > 0 && t[j] == ')'){
				val_cur += 2;
				bal--;
			}
			else if (t[j] == '('){
				bal++;
			}
		}
		if (val_ans > val_cur){
			val_ans = val_cur;
			ans = cur_ans;
		}
	}

	cout << ans << '\n';
}

