#define all(a) a.begin(), a.end()
#define rall(a) a.rbegin(), a.rend()
#define len(a) (int)(a.size())

#ifdef LOCAL
#define __lg(n) log2(n)
#endif

using namespace std;

using ll = long long;
using ull = unsigned long long;
using ld = long double;
using int128 = __int128;

template<typename T>
using PQ = priority_queue<T, vector<T>, greater<>>;

const int N = (1 << 18);

void solve() {
    int n;
    cin >> n;
    vector<int> p(n);
    iota(all(p), 1);
    int k = 0;
    while ((1 << (k)) <= n) ++k;
    vector<string> s(n);
    for (int i = 0; i < k; ++i) cin >> s[i];
    map<string, int> used;
    int pp = 1;
    for (int i = 0; i < k; ++i) pp *= 3;
    for (int i = 0; i < n; ++i) {
        string z;
        for (int j = 0; j < k; ++j) z += s[j][i];
        if (*max_element(all(z)) == '0') {
            cout << 0 << '\n';
            return;
        }
        if (used[z]) {
            cout << 0 << '\n';
            return;
        }
        used[z] = 1;
    }
    vector<bitset<N>> cum(k);
    for (int i = 0; i < k; ++i) {
        for (int j = 0; j < n; ++j) {
            cum[i][j] = bool(s[i][j] - '0');
        }
    }
    vector<bitset<N>> ed((1 << k));
    ed[0].set();
    for (int mask = 0; mask < (1 << k); ++mask) {
        for (int i = 0; i < k; ++i) {
            if ((1 << i) & mask) {
                ed[mask] = ed[mask - (1 << i)] & cum[i];
                break;
            }
        }
    }

    auto get_mask = [&](int mask1, int mask2) -> int {
        int res = 0;
        int pw = 1;
        for (int i = 0; i < k; ++i) {
            if (mask2 & (1 << i)) {
                res += 2 * pw;
            } else if (mask1 & (1 << i)) {
                res += pw;
            }
            pw *= 3;
        }
        return res;
    };

    auto from_mask = [&](int val) -> pair<int, int> {
        int pw = 1;
        for (int i = 0; i < k - 1; ++i) {
            pw *= 3;
        }
        int mask1 = 0, mask2 = 0;
        for (int i = k - 1; i >= 0; --i) {
            int ost = val % pw;
            int tmp = val / pw;
            val = ost;
            if (tmp == 2) {
                mask1 += (1 << i), mask2 += (1 << i);
            } else if (tmp == 1) {
                mask1 += (1 << i);
            }
            pw /= 3;
        }
        return {mask1, mask2};
    };

    vector<ll> dp(pp, 0);
    dp[0] = 1;
    ll ans = 0;
    for (int mask = 0; mask < pp; ++mask) {
        if (dp[mask] == 0) continue;
        auto gd = from_mask(mask);
        int mask1 = gd.first, mask2 = gd.second;
        int cnt = 0;
        for (int i = 0; i < k; ++i) {
            if (mask1 & (1 << i)) {
                ++cnt;
            }
        }
        if (cnt == k) {
            ans += dp[mask];
            continue;
        }
        int deg = k - 1 - cnt;
        if (n & (1 << deg)) {
            for (int i = 0; i < k; ++i) {
                if ((1 << i) & mask1) continue;
                auto mask_res = get_mask(mask1 + (1 << i), mask2 + (1 << i));
                dp[mask_res] += dp[mask];
            }
        } else {
            for (int i = 0; i < k; ++i) {
                if ((1 << i) & mask1) continue;
                auto tmp_bit = ed[mask2] & cum[i];
                if (dp[mask] != 0 && tmp_bit.none()) {
                    dp[get_mask(mask1 + (1 << i), mask2)] += dp[mask];
                }
            }
        }
    }
    cout << ans << '\n';
}

