	int k = 1;
	while((1 << k) <= n){
		k++;
	}

	vector<string> s(k);
	for (int i = 0; i < k; i++){
		cin >> s[i];
	}
	vector<pair<int, int>> ord(k, {0ll, 0ll});
	for (int i = 0; i < k; i++){
		auto& [x, ind] = ord[i];
		ind = i;
		for (int j = 0; j < n; j++){
			x += (s[i][j] == '1');
		}
	}
	sort(ord.rbegin(), ord.rend());

	vector<int> fact(k + 1);
	fact[0] = 1;
	for (int i = 1; i <= k; i++){
		fact[i] = fact[i - 1] * i;
	}

	vector<int> p(n);
	for (int i = 0; i < n; i++){
		for (int j = 0; j < k; j++){
			int bit = s[ord[j].second][i] - '0';
			p[i] ^= (bit << j);
		}
	}
	sort(p.begin(), p.end());
	if (p[0] != 1){
		cout << 0 << '\n';
		return;
	}
	for (int i = 1; i < n; i++){
		if (p[i] != p[i - 1] + 1){
			cout << 0 << '\n';
			return;
		}
	}

	vector<int> cnt(n + 1);
	for (auto [x, ind] : ord){
		cnt[x]++;
	}

	int ans = 1;
	for (int i = 0; i <= n; i++){
		ans *= fact[cnt[i]];
	}
	cout << ans << '\n';
}

