#include<bits/stdc++.h>

using namespace std;

//#define int long long

const int INF = 1000000007;

void solve(){
	int n, a, b;
	cin >> n >> a >> b;

	int g = gcd(a, b);
	a /= g;
	b /= g;

	vector<int> d1, d2;
	for (int i = 1; i * i <= a; i++){
		if (a % i == 0){
			d1.push_back(i);
			if (i * i != a){
				d1.push_back(a / i);
			}
		}
	}

	for (int i = 1; i * i <= b; i++){
		if (b % i == 0){
			d2.push_back(i);
			if (i * i != b){
				d2.push_back(b / i);
			}
		}
	}

	sort(d1.begin(), d1.end());
	sort(d2.begin(), d2.end());

	int sz1 = d1.size();
	int sz2 = d2.size();

	vector<vector<int>> to_d1(sz1, vector<int> (sz1, -1));
	for (int i = 0; i < sz1; i++){
		int u = 0;
		for (int j = i; j >= 0; j--){
			while(u < i && d1[i] > d1[u] * d1[j]){
				u++;
			}
			if (d1[i] % d1[j] == 0 && d1[i] / d1[j] == d1[u]){
				to_d1[i][j] = u;
			}
		}
	}

	vector<vector<int>> to_d2(sz2, vector<int> (sz2, -1));
	for (int i = 0; i < sz2; i++){
		int u = 0;
		for (int j = i; j >= 0; j--){
			while(u < i && d2[i] > d2[u] * d2[j]){
				u++;
			}
			if (d2[i] % d2[j] == 0 && d2[i] / d2[j] == d2[u]){
				to_d2[i][j] = u;
			}
		}
	}

	vector<vector<int>> dels_d1(sz1);
	for (int i = 0; i < sz1; i++){
		for (int j = 0; j <= i; j++){
			if (d1[i] % d1[j] == 0){
				dels_d1[i].emplace_back(j);
			}
		}
	}

	vector<vector<int>> dels_d2(sz2);
	for (int i = 0; i < sz2; i++){
		for (int j = 0; j <= i; j++){
			if (d2[i] % d2[j] == 0){
				dels_d2[i].emplace_back(j);
			}
		}
	}

	vector<vector<int>> dp(sz1, vector<int> (sz2, -1));

	auto go = [&](auto&& self, int x, int y) -> int{
		if (dp[x][y] != -1){
			return dp[x][y];
		}
		if (x == 0 && y == 0){
			return 0;
		}
		dp[x][y] = INF;

		for (int dx : dels_d1[x]){
			for (int dy : dels_d2[y]){
				if (dx == 0 && dy == 0){
					continue;
				}
				dp[x][y] = min(dp[x][y], max(d1[dx], d2[dy]) + self(self, to_d1[x][dx], to_d2[y][dy]));
			}
		}
		return dp[x][y];
	};

	cout << go(go, sz1 - 1, sz2 - 1) << '\n';
}

